import * as Phaser from "phaser";
import { BIRD_SPEED } from "../common/config";
import { CUSTOM_EVENTS, EVENT_BUS } from "../common/event-bus";
import { TILED_LAYER_NAMES } from "../common/tiled/constants";
import {
  FlyingBird,
  MUSIC_BIRD_COLLISION_SLACK_PX,
} from "../entities/critters/flyingBird";
import type { BaseGameScene } from "../scenes/base-game-scene";

export type MusicCarryConfig = {
  scene: BaseGameScene;
  birdType: string;
  allowedRoomId: number;
  allowedRoomIds?: readonly number[];
  approachDistancePx: number;
  exitDistancePx: number;
  onInvalidDestination?: (target: { x: number; y: number }) => void;
  onDebugDrawDropArea?: (
    center: { x: number; y: number },
    width: number,
    height: number,
  ) => void;
  showInvalidDropMarker?: boolean;
};

export class MusicCarryManager {
  readonly #scene: BaseGameScene;
  readonly #birdType: string;
  readonly #allowedRoomIds: Set<number>;
  readonly #approachDistancePx: number;
  readonly #exitDistancePx: number;
  readonly #onInvalidDestination?: (target: { x: number; y: number }) => void;
  readonly #onDebugDrawDropArea?: (
    center: { x: number; y: number },
    width: number,
    height: number,
  ) => void;
  readonly #showInvalidDropMarker: boolean;

  #musicCarryBird: FlyingBird | undefined;
  #invalidDropMarker: Phaser.GameObjects.Graphics | undefined;
  #invalidDropMarkerTween: Phaser.Tweens.Tween | undefined;
  #musicCarryBirdTweenChain: Phaser.Tweens.TweenChain | undefined;
  #musicCarryBirdCollider: Phaser.Physics.Arcade.Collider | undefined;
  #musicCarryPickupPoint:
    | {
        x: number;
        y: number;
      }
    | undefined;

  constructor(config: MusicCarryConfig) {
    this.#scene = config.scene;
    this.#birdType = config.birdType;
    this.#allowedRoomIds = new Set([
      config.allowedRoomId,
      ...(config.allowedRoomIds ?? []),
    ]);
    this.#approachDistancePx = config.approachDistancePx;
    this.#exitDistancePx = config.exitDistancePx;
    this.#onInvalidDestination = config.onInvalidDestination;
    this.#onDebugDrawDropArea = config.onDebugDrawDropArea;
    this.#showInvalidDropMarker = config.showInvalidDropMarker ?? false;
  }

  registerEvents(): void {
    EVENT_BUS.on(
      CUSTOM_EVENTS.MUSIC_BIRD_SUMMON,
      this.#handleMusicBirdSummon,
      this,
    );
  }

  unregisterEvents(): void {
    EVENT_BUS.off(
      CUSTOM_EVENTS.MUSIC_BIRD_SUMMON,
      this.#handleMusicBirdSummon,
      this,
    );
  }

  #handleMusicBirdSummon = (payload?: {
    from: { x: number; y: number };
    to: { x: number; y: number };
  }): void => {
    if (!this.#allowedRoomIds.has(this.#scene.currentRoomId)) {
      EVENT_BUS.emit(CUSTOM_EVENTS.MUSIC_BIRD_SUMMON_FAILED);
      return;
    }
    if (!payload) {
      EVENT_BUS.emit(CUSTOM_EVENTS.MUSIC_BIRD_SUMMON_FAILED);
      return;
    }
    this.#maybeSummonMusicCarryBird(payload);
  };

  #maybeSummonMusicCarryBird(payload: {
    from: { x: number; y: number };
    to: { x: number; y: number };
  }): void {
    if (this.#musicCarryBird) {
      EVENT_BUS.emit(CUSTOM_EVENTS.MUSIC_BIRD_SUMMON_FAILED);
      return;
    }

    const snappedDestination = this.#snapTargetToTileCenter(payload.to);
    if (!this.#isValidDestination(snappedDestination)) {
      if (this.#showInvalidDropMarker) {
        this.#showInvalidDropMarkerAt(snappedDestination);
      }
      if (this.#onInvalidDestination) {
        this.#onInvalidDestination(snappedDestination);
      }
      EVENT_BUS.emit(CUSTOM_EVENTS.MUSIC_BIRD_SUMMON_FAILED);
      return;
    }

    const { from } = payload;
    const to = snappedDestination;
    const dx = to.x - from.x;
    const dy = to.y - from.y;
    const distance = Math.hypot(dx, dy);
    const unitX = distance === 0 ? 0 : dx / distance;
    const unitY = distance === 0 ? 0 : dy / distance;

    const approachPoint = {
      x: from.x - unitX * this.#approachDistancePx,
      y: from.y - unitY * this.#approachDistancePx,
    };
    const exitPoint = {
      x: to.x + unitX * this.#exitDistancePx,
      y: to.y + unitY * this.#exitDistancePx,
    };

    // Get offsets using the static methods from FlyingBird
    const horizontalOffset = FlyingBird.getCarryOffsetX(this.#birdType);
    const verticalOffset = FlyingBird.getCarryOffsetY(this.#birdType);
    const birdPoints = [approachPoint, from, to, exitPoint].map((p) => ({
      x: p.x - horizontalOffset,
      y: p.y - verticalOffset,
    }));

    const bird = new FlyingBird({
      scene: this.#scene,
      color: this.#birdType,
      points: birdPoints,
      canCarry: true,
    });

    this.#musicCarryBird = bird;
    this.#musicCarryPickupPoint = {
      x: birdPoints[1].x,
      y: birdPoints[1].y,
    };
    bird.enableObject();
    const distanceToDuration = (startIndex: number, endIndex: number) => {
      const start = birdPoints[startIndex];
      const end = birdPoints[endIndex];
      return (
        (Phaser.Math.Distance.Between(start.x, start.y, end.x, end.y) /
          BIRD_SPEED) *
        1000
      );
    };

    this.#musicCarryBirdCollider = this.#scene.physics.add.overlap(
      this.#scene.playerObject,
      bird,
      () => {
        this.#attemptMusicBirdPickup(bird);
      },
    );

    const onSegmentStart = (startIndex: number, endIndex: number) => () => {
      bird.checkNextDestination(startIndex, endIndex);
      bird.setToTop();
    };

    const tweens: Phaser.Types.Tweens.TweenBuilderConfig[] = [
      {
        targets: bird,
        x: birdPoints[1].x,
        y: birdPoints[1].y,
        ease: "Linear",
        duration: distanceToDuration(0, 1),
        onStart: onSegmentStart(0, 1),
        onUpdate: () => {
          this.#attemptMusicBirdPickup(bird);
        },
        onComplete: () => {
          this.#attemptMusicBirdPickup(bird);
        },
      },
      {
        targets: bird,
        x: birdPoints[2].x,
        y: birdPoints[2].y,
        ease: "Linear",
        duration: distanceToDuration(1, 2),
        onStart: onSegmentStart(1, 2),
        onComplete: () => {
          bird.dropCarriedPlayer();
          EVENT_BUS.emit(CUSTOM_EVENTS.MUSIC_BIRD_DROPPED, {
            from,
            to,
          });
        },
      },
      {
        targets: bird,
        x: birdPoints[3].x,
        y: birdPoints[3].y,
        ease: "Linear",
        duration: distanceToDuration(2, 3),
        onStart: onSegmentStart(2, 3),
      },
    ];

    this.#musicCarryBirdTweenChain = this.#scene.tweens.chain({
      targets: bird,
      tweens,
      onComplete: () => {
        bird.stopFlyingRoute();
        bird.destroy();
        this.#musicCarryBirdTweenChain = undefined;
        this.#musicCarryBird = undefined;
        this.#musicCarryBirdCollider?.destroy();
        this.#musicCarryBirdCollider = undefined;
        this.#musicCarryPickupPoint = undefined;
      },
    });
    this.#musicCarryBirdTweenChain.play();
  }

  #isValidDestination(target: { x: number; y: number }): boolean {
    const map = this.#scene.tilemap;
    if (!map) {
      return true;
    }

    const collisionLayer = map.getLayer(
      TILED_LAYER_NAMES.COLLISION,
    )?.tilemapLayer;
    if (!collisionLayer) {
      return true;
    }
    const player = this.#scene.playerObject;
    const playerBody = player.physicsBody;
    const bodyWidth = playerBody?.width ?? 16;
    const bodyHeight = playerBody?.height ?? 16;
    const bodyTopLeftX =
      target.x -
      player.displayWidth * player.originX +
      (playerBody?.offset.x ?? 0);
    const bodyTopLeftY =
      target.y -
      player.displayHeight * player.originY +
      (playerBody?.offset.y ?? 0);

    const slack = MUSIC_BIRD_COLLISION_SLACK_PX;
    const collisionWidth = Math.max(0, bodyWidth - slack * 2);
    const collisionHeight = Math.max(0, bodyHeight - slack * 2);

    const withinBounds =
      bodyTopLeftX + slack >= 0 &&
      bodyTopLeftY + slack >= 0 &&
      bodyTopLeftX + slack + collisionWidth <= map.widthInPixels &&
      bodyTopLeftY + slack + collisionHeight <= map.heightInPixels;
    if (!withinBounds) {
      return false;
    }
    const tiles =
      collisionLayer.getTilesWithinWorldXY(
        bodyTopLeftX + slack,
        bodyTopLeftY + slack,
        collisionWidth,
        collisionHeight,
        { isColliding: true, isNotEmpty: true },
      ) ?? [];

    if (this.#onDebugDrawDropArea) {
      this.#onDebugDrawDropArea(
        {
          x: bodyTopLeftX + slack + collisionWidth / 2,
          y: bodyTopLeftY + slack + collisionHeight / 2,
        },
        collisionWidth,
        collisionHeight,
      );
    }

    const collidingTile = tiles.find((tile) => tile?.collides);
    if (collidingTile) {
      return false;
    }

    // Also check partial collision rectangles
    const hasPartial = this.#scene.hasPartialCollision({
      x: bodyTopLeftX + slack,
      y: bodyTopLeftY + slack,
      width: collisionWidth,
      height: collisionHeight,
    });
    return !hasPartial;
  }

  #snapTargetToTileCenter(target: { x: number; y: number }): {
    x: number;
    y: number;
  } {
    const map = this.#scene.tilemap;
    const tileWidth = map?.tileWidth ?? 16;
    const tileHeight = map?.tileHeight ?? 16;
    const player = this.#scene.playerObject;
    const playerBody = player.physicsBody;
    const bodyWidth = playerBody?.width ?? 16;
    const bodyHeight = playerBody?.height ?? 16;
    const bodyTopLeftX =
      target.x -
      player.displayWidth * player.originX +
      (playerBody?.offset.x ?? 0);
    const bodyTopLeftY =
      target.y -
      player.displayHeight * player.originY +
      (playerBody?.offset.y ?? 0);
    const bodyCenterX = bodyTopLeftX + bodyWidth / 2;
    const bodyCenterY = bodyTopLeftY + bodyHeight / 2;

    const snappedCenterX =
      Math.round((bodyCenterX - tileWidth / 2) / tileWidth) * tileWidth +
      tileWidth / 2;
    const snappedCenterY =
      Math.round((bodyCenterY - tileHeight / 2) / tileHeight) * tileHeight +
      tileHeight / 2;

    return {
      x: target.x + (snappedCenterX - bodyCenterX),
      y: target.y + (snappedCenterY - bodyCenterY),
    };
  }

  #attemptMusicBirdPickup(bird: FlyingBird): void {
    if (!this.#musicCarryBird || bird !== this.#musicCarryBird) {
      return;
    }
    if (this.#musicCarryPickupPoint === undefined) {
      return;
    }

    // Only allow pickup once the bird has reached the player position.
    const atPickupPoint =
      Phaser.Math.Distance.Between(
        bird.x,
        bird.y,
        this.#musicCarryPickupPoint.x,
        this.#musicCarryPickupPoint.y,
      ) <= 2;
    if (!atPickupPoint) {
      return;
    }
    bird.tryCarryPlayer(this.#scene.playerObject);
  }

  cleanup(): void {
    this.#musicCarryBirdTweenChain?.stop();
    this.#musicCarryBirdTweenChain = undefined;
    this.#musicCarryBirdCollider?.destroy();
    this.#musicCarryBirdCollider = undefined;
    this.#musicCarryPickupPoint = undefined;
    if (this.#musicCarryBird) {
      this.#musicCarryBird.stopFlyingRoute();
      this.#musicCarryBird.destroy();
      this.#musicCarryBird = undefined;
    }
    this.#clearInvalidDropMarker();
  }

  #showInvalidDropMarkerAt(target: { x: number; y: number }): void {
    this.#clearInvalidDropMarker();

    const playerBody = this.#scene.playerObject.physicsBody;
    const bodyWidth = playerBody?.width ?? 16;
    const bodyHeight = playerBody?.height ?? 16;
    const bodyTopLeftX =
      target.x -
      this.#scene.playerObject.displayWidth * this.#scene.playerObject.originX +
      (playerBody?.offset.x ?? 0);
    const bodyTopLeftY =
      target.y -
      this.#scene.playerObject.displayHeight *
        this.#scene.playerObject.originY +
      (playerBody?.offset.y ?? 0);
    const center = {
      x: bodyTopLeftX + bodyWidth / 2,
      y: bodyTopLeftY + bodyHeight / 2,
    };

    const markerSize = 16;
    const halfSize = markerSize / 2;
    const marker = this.#scene.add.graphics({ x: center.x, y: center.y });
    marker.lineStyle(3, 0xff0000, 1);
    marker.strokeLineShape(
      new Phaser.Geom.Line(-halfSize, -halfSize, halfSize, halfSize),
    );
    marker.strokeLineShape(
      new Phaser.Geom.Line(-halfSize, halfSize, halfSize, -halfSize),
    );
    marker.setDepth(5);

    this.#invalidDropMarkerTween = this.#scene.tweens.add({
      targets: marker,
      alpha: 0.25,
      duration: 350,
      yoyo: true,
      repeat: -1,
    });
    this.#invalidDropMarker = marker;
  }

  #clearInvalidDropMarker(): void {
    if (this.#invalidDropMarkerTween) {
      this.#scene.tweens.remove(this.#invalidDropMarkerTween);
      this.#invalidDropMarkerTween = undefined;
    }
    this.#invalidDropMarker?.destroy();
    this.#invalidDropMarker = undefined;
  }

  clearInvalidDropMarker(): void {
    this.#clearInvalidDropMarker();
  }
}
