import * as Phaser from "phaser";
import {
  ASSET_KEYS,
  BAT_ANIMATION_KEYS,
  BIRD_TYPES,
  GRACKLE_BLACK_ANIMATION_KEYS,
  GRACKLE_BLUE_ANIMATION_KEYS,
  GRACKLE_GREEN_ANIMATION_KEYS,
  GRACKLE_PINK_ANIMATION_KEYS,
  GRACKLE_RED_ANIMATION_KEYS,
  GRACKLE_YELLOW_ANIMATION_KEYS,
} from "../../common/assets";
import { BIRD_MAX_HP, BIRD_SPEED } from "../../common/config";
import { CHARACTER_ACTIVE_STATE, DIRECTION } from "../../common/constants";
import type { AnimationConfig } from "../../components/animation-component";
import { InputComponent } from "../../components/input-component";
import { CHARACTER_STATES } from "../../components/state-machine/states/character-states";
import { IdleState } from "../../components/state-machine/states/idle-state";
import { MoveState } from "../../components/state-machine/states/move-state";
import { CharacterObject } from "../common/character-object";
import type { Player } from "../player/player";

export type FlyingBirdConfig = {
  scene: Phaser.Scene;
  color: string;
  points: { x: number; y: number }[];
  canCarry?: boolean;
};

export const MUSIC_BIRD_COLLISION_SLACK_PX = 0;
export class FlyingBird extends CharacterObject {
  #points: { x: number; y: number }[] = [];
  #flyChain: Phaser.Tweens.TweenChain | undefined;
  #canCarry: boolean;
  #carriedPlayer: Player | undefined;
  #carryOffsetX = 0;
  #carryOffsetY = 0;
  #birdType: string;
  #playerControlLockState:
    | { isMovementLocked: boolean; movementControlsLocked: boolean }
    | undefined;
  #nextPickupAllowedAt = 0;
  static readonly #PICKUP_COOLDOWN_MS = 300;

  constructor(config: FlyingBirdConfig) {
    const { assetKey, animationConfig } = FlyingBird.#getBirdConfig(
      config.color,
    );
    const spawnPosition = config.points[0] ?? { x: 50, y: 50 };

    super({
      id: `bird-${Phaser.Math.RND.uuid()}`,
      scene: config.scene,
      position: spawnPosition,
      assetKey,
      frame: 0,
      isPlayer: false,
      animationConfig,
      speed: BIRD_SPEED,
      inputComponent: new InputComponent(),
      isInvulnerable: true,
      maxHP: BIRD_MAX_HP,
      shouldFlipLeft: false,
    });

    this.#points = config.points;
    this.#canCarry = config.canCarry ?? false;
    this.#birdType = config.color;

    this.setOrigin(0, 0);
    this.setDepth(4);

    config.scene.events.on(Phaser.Scenes.Events.UPDATE, this.update, this);
    config.scene.events.once(Phaser.Scenes.Events.SHUTDOWN, () => {
      config.scene.events.off(Phaser.Scenes.Events.UPDATE, this.update, this);
      this.#dropCarriedPlayer();
    });

    this._stateMachine.addState(new IdleState(this));
    this._stateMachine.addState(new MoveState(this));
    this._stateMachine.setState(CHARACTER_STATES.MOVE_STATE);
  }

  public onTweenStart(
    _tween: Phaser.Tweens.Tween,
    targets: FlyingBird[],
    start: number,
    end: number,
  ): void {
    const bird = targets[0];
    bird.checkNextDestination(start, end);
    bird.setToTop();
  }

  public checkNextDestination(start: number, end: number): void {
    const dx = this.#points[end].x - this.#points[start].x;
    const dy = this.#points[end].y - this.#points[start].y;

    // Use the dominant axis to determine direction
    if (Math.abs(dx) >= Math.abs(dy)) {
      this.direction = dx > 0 ? DIRECTION.RIGHT : DIRECTION.LEFT;
    } else {
      this.direction = dy > 0 ? DIRECTION.DOWN : DIRECTION.UP;
    }
    this._animationComponent.playAnimation(`WALK_${this.direction}`);
  }

  public update = (): void => {
    super.update();
    this.#updateCarriedPlayerPosition();
  };

  public tryCarryPlayer(player: Player): void {
    if (player.isDefeated) {
      return;
    }
    if (!this.#canCarry) {
      return;
    }
    if (this.#carriedPlayer) {
      return;
    }
    if (!this.active || !this.body?.enable) {
      return;
    }
    if (this.scene.time.now < this.#nextPickupAllowedAt) {
      return;
    }
    this.#startCarrying(player);
  }

  /**
   * Get the horizontal carry offset based on sprite dimensions.
   * Can be called as a static method with bird type, or instance method.
   */
  public static getCarryOffsetX(birdType: string): number {
    switch (birdType) {
      case BIRD_TYPES.BAT:
        return 48;
      default:
        return 16;
    }
  }

  /**
   * Get the vertical carry offset based on sprite dimensions.
   * Can be called as a static method with bird type, or instance method.
   */
  public static getCarryOffsetY(birdType: string): number {
    switch (birdType) {
      case BIRD_TYPES.BAT:
        return 80;
      default:
        return 32;
    }
  }

  #startCarrying(player: Player): void {
    this.#carriedPlayer = player;
    this.#playerControlLockState = {
      isMovementLocked: player.controls.isMovementLocked,
      movementControlsLocked: player.controls.movementControlsLocked,
    };
    // Set offsets based on actual sprite dimensions
    this.#carryOffsetX = FlyingBird.getCarryOffsetX(this.#birdType);
    this.#carryOffsetY = FlyingBird.getCarryOffsetY(this.#birdType);
    player.setIsBeingCarried(true);
    player.controls.reset();
    player.controls.isMovementLocked = true;
    player.controls.movementControlsLocked = true;
    player.physicsBody.setVelocity(0, 0);
    player.stateMachine.setState(CHARACTER_STATES.IDLE_STATE);
  }

  #updateCarriedPlayerPosition(): void {
    if (!this.#carriedPlayer) {
      return;
    }
    const player = this.#carriedPlayer;
    player.setPosition(
      this.x + this.#carryOffsetX,
      this.y + this.#carryOffsetY,
    );
    player.physicsBody.setVelocity(0, 0);
  }

  #dropCarriedPlayer(): void {
    if (!this.#carriedPlayer) {
      return;
    }
    const player = this.#carriedPlayer;
    player.setPosition(
      this.x + this.#carryOffsetX,
      this.y + this.#carryOffsetY,
    );
    player.controls.reset();
    player.controls.isMovementLocked =
      this.#playerControlLockState?.isMovementLocked ?? false;
    player.controls.movementControlsLocked =
      this.#playerControlLockState?.movementControlsLocked ?? false;
    player.physicsBody.setVelocity(0, 0);
    player.setIsBeingCarried(false);
    this.#carryOffsetX = 0;
    this.#carryOffsetY = 0;

    this.#carriedPlayer = undefined;
    this.#playerControlLockState = undefined;
    this.#nextPickupAllowedAt =
      this.scene.time.now + FlyingBird.#PICKUP_COOLDOWN_MS;
  }

  public startFlyingRoute(): void {
    if (this.#points.length < 3) {
      return;
    }

    if (!this.#flyChain) {
      const tweenBuilderArray: Phaser.Types.Tweens.TweenBuilderConfig[] = [];

      // Add all the points from the start + 1 (because our spawn position is the start) onward
      const boundOnTweenStart = this.onTweenStart.bind(this);
      let i = 1;
      for (i; i < this.#points.length; i++) {
        const prev = this.#points[i - 1];
        const curr = this.#points[i];
        const distance = Phaser.Math.Distance.Between(
          prev.x,
          prev.y,
          curr.x,
          curr.y,
        );
        const duration = (distance / BIRD_SPEED) * 1000;

        tweenBuilderArray.push({
          targets: this,
          x: curr.x,
          y: curr.y,
          ease: "Linear",
          onStart: boundOnTweenStart,
          onStartParams: [i - 1, i],
          onCompleteParams: [i - 1, i],
          duration,
        });
      }

      // Then add the points from length - 2 (i.e. last element - 1) to start to have the chain yoyo.
      i = this.#points.length - 2;
      for (i; i >= 0; i--) {
        const prev = this.#points[i + 1];
        const curr = this.#points[i];
        const distance = Phaser.Math.Distance.Between(
          prev.x,
          prev.y,
          curr.x,
          curr.y,
        );
        const duration = (distance / BIRD_SPEED) * 1000;

        tweenBuilderArray.push({
          targets: this,
          x: curr.x,
          y: curr.y,
          ease: "Linear",
          onStart: boundOnTweenStart,
          onStartParams: [i + 1, i],
          onCompleteParams: [i + 1, i],
          duration,
        });
      }

      this.#flyChain = this.scene.tweens.chain({
        targets: this,
        tweens: tweenBuilderArray,
        repeat: -1,
        paused: true,
        persist: true,
      });
    }

    this.activeState = CHARACTER_ACTIVE_STATE.REVEALED;
    this.enableObject();
    this.setToTop();
    this._animationComponent.playAnimation("WALK_RIGHT");
    this.#flyChain.play();
  }

  public stopFlyingRoute(): void {
    this.#dropCarriedPlayer();
    this.#flyChain?.stop();
    this.stop();
    this.disableObject();
    this.activeState = CHARACTER_ACTIVE_STATE.HIDDEN;
  }

  public dropCarriedPlayer(): void {
    this.#dropCarriedPlayer();
  }

  static #getBirdConfig(color: string): {
    assetKey: string;
    animationConfig: AnimationConfig;
  } {
    const grackleAnim = (keys: {
      WALK_DOWN: string;
      WALK_LEFT: string;
      WALK_RIGHT: string;
      WALK_UP: string;
    }): AnimationConfig => ({
      IDLE_DOWN: { key: keys.WALK_DOWN, repeat: -1, ignoreIfPlaying: true },
      IDLE_UP: { key: keys.WALK_UP, repeat: -1, ignoreIfPlaying: true },
      IDLE_LEFT: { key: keys.WALK_LEFT, repeat: -1, ignoreIfPlaying: true },
      IDLE_RIGHT: { key: keys.WALK_RIGHT, repeat: -1, ignoreIfPlaying: true },
      WALK_DOWN: { key: keys.WALK_DOWN, repeat: -1, ignoreIfPlaying: true },
      WALK_UP: { key: keys.WALK_UP, repeat: -1, ignoreIfPlaying: true },
      WALK_LEFT: { key: keys.WALK_LEFT, repeat: -1, ignoreIfPlaying: true },
      WALK_RIGHT: { key: keys.WALK_RIGHT, repeat: -1, ignoreIfPlaying: true },
    });

    switch (color) {
      case BIRD_TYPES.BAT:
        return {
          assetKey: ASSET_KEYS.BAT,
          animationConfig: grackleAnim(BAT_ANIMATION_KEYS),
        };
      case BIRD_TYPES.GRACKLE_BLACK:
        return {
          assetKey: ASSET_KEYS.GRACKLE_BLACK,
          animationConfig: grackleAnim(GRACKLE_BLACK_ANIMATION_KEYS),
        };
      case BIRD_TYPES.GRACKLE_BLUE:
        return {
          assetKey: ASSET_KEYS.GRACKLE_BLUE,
          animationConfig: grackleAnim(GRACKLE_BLUE_ANIMATION_KEYS),
        };
      case BIRD_TYPES.GRACKLE_GREEN:
        return {
          assetKey: ASSET_KEYS.GRACKLE_GREEN,
          animationConfig: grackleAnim(GRACKLE_GREEN_ANIMATION_KEYS),
        };
      case BIRD_TYPES.GRACKLE_PINK:
        return {
          assetKey: ASSET_KEYS.GRACKLE_PINK,
          animationConfig: grackleAnim(GRACKLE_PINK_ANIMATION_KEYS),
        };
      case BIRD_TYPES.GRACKLE_RED:
        return {
          assetKey: ASSET_KEYS.GRACKLE_RED,
          animationConfig: grackleAnim(GRACKLE_RED_ANIMATION_KEYS),
        };
      case BIRD_TYPES.GRACKLE_YELLOW:
      default:
        return {
          assetKey: ASSET_KEYS.GRACKLE_YELLOW,
          animationConfig: grackleAnim(GRACKLE_YELLOW_ANIMATION_KEYS),
        };
    }
  }
}
